package com.bosspbtimer;

import java.util.Objects;

final class BossDefinition
{
	private final String encounterName;
	private final boolean completesEncounter;

	BossDefinition(String encounterName, boolean completesEncounter)
	{
		this.encounterName = Objects.requireNonNull(encounterName);
		this.completesEncounter = completesEncounter;
	}

	String getEncounterName()
	{
		return encounterName;
	}

	boolean completesEncounter()
	{
		return completesEncounter;
	}
}

package com.bosspbtimer;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(BossPbTimerConfig.GROUP)
public interface BossPbTimerConfig extends Config
{
	String GROUP = "bosspbtimer";

	@ConfigItem(
		keyName = "showWhenIdle",
		name = "Show between kills",
		description = "Keep the overlay visible when no boss fight is active",
		position = 0
	)
	default boolean showWhenIdle()
	{
		return true;
	}

	@ConfigItem(
		keyName = "announcePersonalBest",
		name = "Announce new PB",
		description = "Add a local game message when you set a new personal best",
		position = 1
	)
	default boolean announcePersonalBest()
	{
		return true;
	}
}

package com.bosspbtimer;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

final class BossPbTimerOverlay extends OverlayPanel
{
	private static final Color PB_COLOR = new Color(80, 220, 120);

	private final BossPbTimerPlugin plugin;
	private final BossPbTimerConfig config;

	@Inject
	BossPbTimerOverlay(BossPbTimerPlugin plugin, BossPbTimerConfig config)
	{
		super(plugin);
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setMovable(true);
		setSnappable(true);
		setResizable(false);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		BossTimerState timer = plugin.getTimer();
		if (!timer.isActive() && !config.showWhenIdle())
		{
			return null;
		}

		panelComponent.getChildren().add(TitleComponent.builder()
			.text("Boss PB Timer")
			.color(Color.WHITE)
			.build());

		String boss = timer.isActive() ? timer.getActiveBoss() : timer.getLastBoss();
		panelComponent.getChildren().add(LineComponent.builder()
			.left("Boss")
			.right(boss == null ? "Waiting..." : boss)
			.build());

		if (timer.isActive())
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Current")
				.right(DurationFormatter.format(timer.elapsedMillis(plugin.getCurrentGameTick())))
				.rightColor(Color.WHITE)
				.build());
		}
		else if (timer.getLastBoss() != null)
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Last")
				.right(DurationFormatter.format(timer.getLastDurationMillis()))
				.rightColor(timer.wasLastPersonalBest() ? PB_COLOR : Color.WHITE)
				.build());
		}

		long personalBest = boss == null ? -1 : plugin.getPersonalBest(boss);
		panelComponent.getChildren().add(LineComponent.builder()
			.left("PB")
			.right(DurationFormatter.format(personalBest))
			.rightColor(personalBest >= 0 ? PB_COLOR : Color.LIGHT_GRAY)
			.build());

		panelComponent.setPreferredSize(new Dimension(160, 0));
		return super.render(graphics);
	}
}

package com.bosspbtimer;

import com.google.gson.Gson;
import com.google.inject.Provides;
import javax.inject.Inject;
import net.runelite.api.Actor;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.InteractingChanged;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.NpcSpawned;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.Text;

@PluginDescriptor(
	name = "Boss PB Timer",
	description = "Times boss fights and remembers your fastest time for each boss",
	tags = {"boss", "pb", "personal best", "timer", "pvm", "combat"}
)
public class BossPbTimerPlugin extends Plugin
{
	private static final String PERSONAL_BESTS_KEY = "personalBests";
	private static final int MISSING_BOSS_TICKS_BEFORE_CANCEL = 8;
	private static final int BRUTUS_SPAWN_START_WINDOW_TICKS = 5;

	@Inject
	private Client client;

	@Inject
	private ConfigManager configManager;

	@Inject
	private Gson gson;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private BossPbTimerOverlay overlay;

	@Inject
	private BossPbTimerConfig config;

	private final BossTimerState timer = new BossTimerState();
	private PersonalBestData personalBests = new PersonalBestData();
	private int missingBossTicks;
	private String pendingOfficialBoss;
	private int pendingOfficialUntilTick;
	private int brutusSpawnTick = -1;

	@Provides
	BossPbTimerConfig provideConfig(ConfigManager manager)
	{
		return manager.getConfig(BossPbTimerConfig.class);
	}

	@Override
	protected void startUp()
	{
		loadPersonalBests();
		timer.cancel();
		missingBossTicks = 0;
		pendingOfficialBoss = null;
		brutusSpawnTick = -1;
		overlayManager.add(overlay);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		timer.cancel();
		missingBossTicks = 0;
		pendingOfficialBoss = null;
		brutusSpawnTick = -1;
	}

	@Subscribe
	public void onNpcSpawned(NpcSpawned event)
	{
		NPC npc = event.getNpc();
		String name = npc.getName();
		if (isBrutus(name))
		{
			// NPC spawn events also fire while logging in. Remember the tick, but do not
			// start until Brutus actually interacts with the local player.
			brutusSpawnTick = client.getTickCount();
		}
	}

	@Subscribe
	public void onInteractingChanged(InteractingChanged event)
	{
		Player localPlayer = client.getLocalPlayer();
		if (localPlayer == null)
		{
			return;
		}

		Actor source = event.getSource();
		Actor target = event.getTarget();
		NPC boss = null;
		if (source == localPlayer && target instanceof NPC)
		{
			boss = (NPC) target;
		}
		else if (target == localPlayer && source instanceof NPC)
		{
			boss = (NPC) source;
		}

		if (boss == null)
		{
			return;
		}
		BossDefinition definition = BossRegistry.find(boss.getName());
		int currentTick = client.getTickCount();
		int startTick = currentTick;
		if (isBrutus(boss.getName()) && brutusSpawnTick >= 0
			&& currentTick - brutusSpawnTick <= BRUTUS_SPAWN_START_WINDOW_TICKS)
		{
			startTick = brutusSpawnTick;
		}
		if (definition != null && timer.start(definition.getEncounterName(), startTick))
		{
			missingBossTicks = 0;
			brutusSpawnTick = -1;
		}
	}

	@Subscribe
	public void onActorDeath(ActorDeath event)
	{
		if (!timer.isActive())
		{
			return;
		}
		if (event.getActor() == client.getLocalPlayer())
		{
			timer.cancel();
			return;
		}
		if (!(event.getActor() instanceof NPC))
		{
			return;
		}

		NPC npc = (NPC) event.getActor();
		BossDefinition definition = BossRegistry.find(npc.getName());
		if (definition == null || !definition.completesEncounter()
			|| !definition.getEncounterName().equals(timer.getActiveBoss()))
		{
			return;
		}

		String boss = timer.getActiveBoss();
		int currentTick = client.getTickCount();
		long duration = timer.elapsedMillis(currentTick);
		boolean isPersonalBest = personalBests.record(boss, duration);
		timer.finish(currentTick, isPersonalBest);
		pendingOfficialBoss = boss;
		pendingOfficialUntilTick = currentTick + 5;
		missingBossTicks = 0;
		if (isPersonalBest)
		{
			persistPersonalBests();
			if (config.announcePersonalBest())
			{
				client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
					"Boss PB Timer: New " + boss + " PB — "
						+ DurationFormatter.format(duration), null);
			}
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.GAMEMESSAGE && event.getType() != ChatMessageType.SPAM)
		{
			return;
		}

		String message = Text.removeTags(event.getMessage());
		long officialDuration = DurationFormatter.parseFightDuration(message);
		if (officialDuration < 0)
		{
			return;
		}

		String boss = pendingOfficialBoss != null ? pendingOfficialBoss : timer.getActiveBoss();
		if (boss == null)
		{
			return;
		}
		if (timer.isActive())
		{
			timer.finish(client.getTickCount(), false);
			missingBossTicks = 0;
		}
		long officialPersonalBest = DurationFormatter.parsePersonalBest(message);
		boolean wasPersonalBest;
		boolean changed;
		if (officialPersonalBest >= 0)
		{
			wasPersonalBest = officialDuration <= officialPersonalBest;
			changed = personalBests.set(boss, officialPersonalBest);
		}
		else
		{
			wasPersonalBest = personalBests.record(boss, officialDuration);
			changed = wasPersonalBest;
		}

		timer.correctLastDuration(boss, officialDuration, wasPersonalBest);
		if (changed)
		{
			persistPersonalBests();
		}
		pendingOfficialBoss = null;
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (brutusSpawnTick >= 0
			&& client.getTickCount() - brutusSpawnTick > BRUTUS_SPAWN_START_WINDOW_TICKS)
		{
			brutusSpawnTick = -1;
		}
		if (pendingOfficialBoss != null && client.getTickCount() > pendingOfficialUntilTick)
		{
			pendingOfficialBoss = null;
			brutusSpawnTick = -1;
		}
		if (!timer.isActive())
		{
			return;
		}

		boolean bossPresent = client.getNpcs().stream()
			.map(NPC::getName)
			.map(BossRegistry::find)
			.anyMatch(definition -> definition != null
				&& definition.getEncounterName().equals(timer.getActiveBoss()));
		if (bossPresent)
		{
			missingBossTicks = 0;
			pendingOfficialBoss = null;
		}
		else if (++missingBossTicks >= MISSING_BOSS_TICKS_BEFORE_CANCEL)
		{
			timer.cancel();
			missingBossTicks = 0;
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() != GameState.LOGGED_IN && event.getGameState() != GameState.LOADING)
		{
			timer.cancel();
			missingBossTicks = 0;
			pendingOfficialBoss = null;
			brutusSpawnTick = -1;
		}
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		timer.cancel();
		missingBossTicks = 0;
		pendingOfficialBoss = null;
		brutusSpawnTick = -1;
		loadPersonalBests();
	}

	BossTimerState getTimer()
	{
		return timer;
	}

	int getCurrentGameTick()
	{
		return client.getTickCount();
	}

	long getPersonalBest(String boss)
	{
		return personalBests.get(boss);
	}

	private void loadPersonalBests()
	{
		String serialized = configManager.getRSProfileConfiguration(BossPbTimerConfig.GROUP, PERSONAL_BESTS_KEY);
		if (serialized == null || serialized.isEmpty())
		{
			personalBests = new PersonalBestData();
			return;
		}
		try
		{
			PersonalBestData loaded = gson.fromJson(serialized, PersonalBestData.class);
			personalBests = loaded != null && loaded.isValid() ? loaded : new PersonalBestData();
		}
		catch (RuntimeException ignored)
		{
			personalBests = new PersonalBestData();
		}
	}

	private void persistPersonalBests()
	{
		configManager.setRSProfileConfiguration(BossPbTimerConfig.GROUP, PERSONAL_BESTS_KEY,
			gson.toJson(personalBests));
	}

	private static boolean isBrutus(String npcName)
	{
		return "Brutus".equalsIgnoreCase(npcName) || "Demonic Brutus".equalsIgnoreCase(npcName);
	}
}

