package com.bosspbtimer;

final class BossTimerState
{
	private static final long MILLIS_PER_GAME_TICK = 600L;

	private String activeBoss;
	private int startedAtTick;
	private String lastBoss;
	private long lastDurationMillis;
	private boolean lastWasPersonalBest;

	boolean start(String boss, int currentTick)
	{
		if (boss == null || boss.equals(activeBoss))
		{
			return false;
		}
		activeBoss = boss;
		startedAtTick = currentTick;
		return true;
	}

	long finish(int currentTick, boolean personalBest)
	{
		if (activeBoss == null)
		{
			return -1;
		}
		long duration = elapsedMillis(currentTick);
		lastBoss = activeBoss;
		lastDurationMillis = duration;
		lastWasPersonalBest = personalBest;
		activeBoss = null;
		startedAtTick = 0;
		return duration;
	}

	void correctLastDuration(String boss, long durationMillis, boolean personalBest)
	{
		if (boss != null && boss.equals(lastBoss) && durationMillis >= 0)
		{
			lastDurationMillis = durationMillis;
			lastWasPersonalBest = personalBest;
		}
	}

	void cancel()
	{
		activeBoss = null;
		startedAtTick = 0;
	}

	boolean isActive()
	{
		return activeBoss != null;
	}

	String getActiveBoss()
	{
		return activeBoss;
	}

	long elapsedMillis(int currentTick)
	{
		if (activeBoss == null)
		{
			return 0;
		}
		return Math.max(0L, (long) currentTick - startedAtTick) * MILLIS_PER_GAME_TICK;
	}

	String getLastBoss()
	{
		return lastBoss;
	}

	long getLastDurationMillis()
	{
		return lastDurationMillis;
	}

	boolean wasLastPersonalBest()
	{
		return lastWasPersonalBest;
	}
}

package com.bosspbtimer;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

final class DurationFormatter
{
	private static final Pattern FIGHT_DURATION = Pattern.compile(
		"(?i)fight duration:?\\s*([0-9]+(?::[0-9]{1,2}){1,2}(?:\\.[0-9]{1,3})?)");
	private static final Pattern PERSONAL_BEST = Pattern.compile(
		"(?i)(?:new\\s+)?personal best:?\\s*([0-9]+(?::[0-9]{1,2}){1,2}(?:\\.[0-9]{1,3})?)");

	private DurationFormatter()
	{
	}

	static String format(long millis)
	{
		if (millis < 0)
		{
			return "--:--";
		}
		long hours = millis / 3_600_000L;
		long minutes = (millis / 60_000L) % 60;
		long seconds = (millis / 1_000L) % 60;
		long hundredths = (millis % 1_000L) / 10L;
		String base = hours > 0
			? String.format("%d:%02d:%02d", hours, minutes, seconds)
			: String.format("%02d:%02d", minutes, seconds);
		return String.format("%s.%02d", base, hundredths);
	}

	static long parseFightDuration(String message)
	{
		return parseMatchedDuration(FIGHT_DURATION.matcher(message));
	}

	static long parsePersonalBest(String message)
	{
		return parseMatchedDuration(PERSONAL_BEST.matcher(message));
	}

	private static long parseMatchedDuration(Matcher matcher)
	{
		if (!matcher.find())
		{
			return -1;
		}

		String[] minuteAndSecond = matcher.group(1).split(":");
		long hours = minuteAndSecond.length == 3 ? Long.parseLong(minuteAndSecond[0]) : 0;
		long minutes = Long.parseLong(minuteAndSecond[minuteAndSecond.length - 2]);
		String[] secondAndFraction = minuteAndSecond[minuteAndSecond.length - 1].split("\\.");
		long seconds = Long.parseLong(secondAndFraction[0]);
		long milliseconds = 0;
		if (secondAndFraction.length == 2)
		{
			String fraction = (secondAndFraction[1] + "000").substring(0, 3);
			milliseconds = Long.parseLong(fraction);
		}
		return hours * 3_600_000L + minutes * 60_000L + seconds * 1_000L + milliseconds;
	}
}

package com.bosspbtimer;

import java.util.HashMap;
import java.util.Map;

final class PersonalBestData
{
	static final int CURRENT_VERSION = 1;

	int version = CURRENT_VERSION;
	Map<String, Long> personalBests = new HashMap<>();

	long get(String boss)
	{
		Long value = personalBests.get(boss);
		return value == null || value < 0 ? -1 : value;
	}

	boolean record(String boss, long durationMillis)
	{
		long previous = get(boss);
		if (durationMillis < 0 || (previous >= 0 && durationMillis >= previous))
		{
			return false;
		}
		personalBests.put(boss, durationMillis);
		return true;
	}

	boolean set(String boss, long durationMillis)
	{
		if (boss == null || durationMillis < 0 || durationMillis == get(boss))
		{
			return false;
		}
		personalBests.put(boss, durationMillis);
		return true;
	}

	boolean isValid()
	{
		return version == CURRENT_VERSION && personalBests != null;
	}
}

